mapper.select:
SELECT tab.* FROM( select ( select hbm.bp_class from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_class, ( select hbm.phone from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as phone, ( select hbm.TAXPAYER_TYPE from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as TAXPAYER_TYPE, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb,hls_bp_master hbm where hbm.bp_id=fpb.bp_id and scvb.code_id = scb.code_id and scb.code = 'FND.TAXPAYER_TYPE' and scvb.value = hbm.TAXPAYER_TYPE )as TAXPAYER_TYPE_DESC, ( select hbm.INVOICE_TITLE from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_TITLE, ( select hbm.INVOICE_BP_ADDRESS_PHONE_NUM from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_BP_ADDRESS_PHONE_NUM, ( select hbm.INVOICE_BP_BANK_ACCOUNT from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_BP_BANK_ACCOUNT, ( select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_code, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_name, ( select hbt.description from hls_bp_type hbt where hbt.bp_type=fpb.bp_role_type )as prj_role, ( SELECT hbm.LOAN_CARD_NUM FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS LOAN_CARD_NUM, ( SELECT hbm.ID_TYPE FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS ID_TYPE, ( SELECT hbm.ID_CARD_NO FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS ID_CARD_NO, (select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.bp_role_type and scb.code='FCT.BP_TYPE') as bpRoleTypeDesc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.communal_currency and scb.code='FCT.ACCOUNT_CURRENCY' ) as communal_currency_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.communal_other_currency and scb.code='FCT.ACCOUNT_CURRENCY' ) as communal_other_currency_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.guarantee_type and scb.code='FND_GUARANTEE_FORM' )as guarantee_type_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.np_guarantee_type and scb.code='NP.GUARANTEE_TYPE' )as np_guarantee_type_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.secured_party and scb.code='SECURED_PARTY' )as secured_party_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.collateral_type and scb.code in ('FND_MORTGAGE_CATEGORY', 'FND_PLEDGE_CATEGORY') ) as collateral_type_desc, fpb.serial_number, fpb.contract_number, fpb.project_bp_id, fpb.project_id, fpb.chance_id, fpb.bp_id, fpb.bp_role_type, fpb.credit_grantor_party, fpb.principal_repayment_party, fpb.interest_repayment_party, fpb.down_repayment_party, fpb.use_fee_repayment_party, fpb.compensation_repayment_party, fpb.repay_guarantee_party, fpb.guarantee_type, fpb.guarantee_amount, fpb.mortgage_guarantee_amount, fpb.mortgage_gua_amt_capital, fpb.mortgage_rate, fpb.mortgage_available_amount, fpb.mortgage_avail_amt_capital, fpb.pledge_amount, fpb.pledge_amount_capital, fpb.pledge_rate, fpb.repay_guarantee_sub_amount, fpb.description, fpb.bank_account_id, fpb.address_id, fpb.contact_info_id, fpb.COMMUNAL_CURRENCY, fpb.COMMUNAL_OTHER_CURRENCY, fpb.COMMUNAL_VALUE, fpb.MORTGAGE_EVALUATION_DATE, fpb.MORTGAGE_EVALUATION_NAME, fpb.MORTGAGE_EVALUATION_CODE, fpb.COLLATERAL_TYPE, fpb.REGISTRATION_AUTHORITY, fpb.REGISTRATION_DATE, fpb.MORTGAGE_DESC, fpb.COLLATERAL_CODE, fpb.NP_GUARANTEE_TYPE, fpb.SECURED_PARTY, fpb.EXPIRY_DATE, HBMBA.BANK_ACCOUNT_NUM, HBMBA.BANK_ACCOUNT_NAME, HBMBA.BANK_FULL_NAME, HBMBA.BANK_BRANCH_NAME, concat(concat(concat(concat(HBMA.country, ( SELECT t1.DESCRIPTION FROM FND_PROVINCE t1 WHERE t1.province = HBMA.province )), ( SELECT t1.DESCRIPTION FROM FND_CITY t1 WHERE t1.city = HBMA.city )), ( SELECT t1.DESCRIPTION FROM FND_DISTRICT t1 WHERE t1.district = HBMA.district)), HBMA.address) as addressInfo, concat(HBMCI.CONTACT_PERSON,HBMCI.CELL_PHONE) as contact_info from fct_project_bp fpb left join Hls_Bp_Master_Bank_Account HBMBA on fpb.BANK_ACCOUNT_ID=HBMBA.BANK_ACCOUNT_ID left join hls_bp_master_address HBMA on HBMA.ADDRESS_ID=fpb.ADDRESS_ID left join hls_bp_master_contact_info HBMCI on HBMCI.CONTACT_INFO_ID=fpb.CONTACT_INFO_ID ORDER BY fpb.CREATION_DATE ASC )tab
1 = 1
and tab.project_id=#{projectId}
and tab.chance_id=#{chanceId}
and tab.bp_role_type=#{bpRoleType}
and tab.bp_role_type in ('SELLER','BUYER')
and tab.credit_grantor_party=#{creditGrantorParty}
and tab.credit_grantor_party != 'Y' and tab.bp_class = #{bpClass}
AND tab.bp_name like concat('%',concat(#{bpName},'%'))
AND tab.bp_code like concat('%',concat(#{bpCode},'%'))
AND (1=2 or tab.repay_guarantee_party ='Y')
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 AND (1=2 or tab.principal_repayment_party ='Y')
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 AND (1=2 or tab.interest_repayment_party ='Y')
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 AND (1=2 or tab.use_fee_repayment_party ='Y')

select tab.* from (SELECT fpb.PRJ_BP_ID as prj_bp_id, fpb.PRJ_BP_ID as project_bp_id, 'LEASE' as business_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'LEANDING_TYPE' and v.code_value = 'LEASE') business_type_n, pp.APPROVAL_NUMBER, fc.CONTRACT_NAME, fc.CONTRACT_NUMBER MAIN_CONTRACT_NUMBER, fpb.SERIAL_NUMBER, hbm.BP_ID as BP_ID, hbm.bp_name AS BP_NAME, ta.bp_name credit_grantor_name, fc.sign_date, fc.INCEPTION_OF_LEASE as rate_valid_from , (SELECT MAX(ccc.DUE_DATE) FROM CON_CONTRACT_CASHFLOW ccc WHERE ccc.CONTRACT_ID = fc.contract_id) AS rate_valid_to, CASE WHEN (fc.contract_status = 'TERMINATE' or fc.contract_status = 'END') THEN 'N' ELSE 'Y' END contract_status, CASE WHEN (fc.contract_status = 'TERMINATE' or fc.contract_status = 'END') THEN '否' ELSE '是' END contract_status_n, CASE WHEN hbm.bp_class = 'NP' THEN hbm.id_card_no ELSE hbm.loan_card_num END loan_card_num, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FCT.ACCOUNT_CURRENCY' AND scvb.VALUE = fpb.COMMUNAL_CURRENCY) AS COMMUNAL_CURRENCY, nvl(fpb.guarantee_amount, 0) guarantee_amount_str, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_GUARANTEE_FORM' AND scvb.value = fpb.guarantee_type) AS guarantee_type, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FCT.ACCOUNT_CURRENCY' AND scvb.VALUE = fpb.COMMUNAL_OTHER_CURRENCY) AS COMMUNAL_OTHER_CURRENCY, fpb.MORTGAGE_EVALUATION_DATE, fpb.MORTGAGE_EVALUATION_NAME, fpb.MORTGAGE_EVALUATION_CODE, CASE WHEN fpb.BP_ROLE_TYPE = 'PLEDGOR' THEN ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_PLEDGE_CATEGORY' AND scvb.VALUE = fpb.COLLATERAL_TYPE) WHEN fpb.BP_ROLE_TYPE = 'MORTGAGOR' THEN ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_MORTGAGE_CATEGORY' AND scvb.VALUE = fpb.COLLATERAL_TYPE) ELSE fpb.COLLATERAL_TYPE END AS COLLATERAL_TYPE, fpb.REGISTRATION_AUTHORITY, fpb.REGISTRATION_DATE, fpb.MORTGAGE_DESC, fpb.COLLATERAL_CODE, nvl(fpb.COMMUNAL_VALUE, 0) COMMUNAL_VALUE, fpb.EXPIRY_DATE, fpb.REMARKS AS REMARKS FROM PRJ_PROJECT_BP fpb LEFT JOIN hls_bp_master hbm ON hbm.bp_id = fpb.bp_id LEFT JOIN CON_CONTRACT fc ON fpb.PROJECT_ID = fc.PROJECT_ID LEFT JOIN PRJ_PROJECT pp ON pp.PROJECT_ID = fc.PROJECT_ID LEFT JOIN ( SELECT fpb.PROJECT_ID, hbm.BP_NAME FROM PRJ_PROJECT_BP fpb LEFT JOIN hls_bp_master hbm ON fpb.BP_ID = hbm.BP_ID WHERE fpb.BP_TYPE = 'TENANT' ) ta ON ta.project_id = fpb.project_id WHERE fpb.PROJECT_ID IS NOT NULL AND fc.DATA_CLASS = 'NORMAL' AND ( fc.CONTRACT_STATUS IN ('INCEPT', 'TERMINATE','END') OR ( fc.CONTRACT_STATUS = 'PENDING' AND ( SELECT COUNT(0) FROM CON_CONTRACT fcc WHERE fcc.ref_contract_id = fc.contract_id AND fcc.contract_status = 'INCEPT' AND fcc.data_class = 'CHANGE_REQ' )> 0 ) )
and fpb.project_id=#{projectId}
and fpb.bp_role_type=#{bpRoleType}
and fpb.bp_role_type in ('SELLER','BUYER')
AND hbm.bp_name like '%'||#{bpName}||'%'
AND ta.bp_name like '%'||#{creditGrantorName}||'%'
AND fc.contract_name like '%'||#{contractName}||'%'
AND hbm.bp_code like '%'||#{bpCode}||'%'
AND fpb.PRJ_BP_ID = #{projectBpId}
UNION SELECT fpb.project_bp_id as prj_bp_id, fpb.project_bp_id as project_bp_id, 'FACTOR' business_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'LEANDING_TYPE' and v.code_value = 'FACTOR') business_type_n, fp.approval_number as approval_number, fp.contract_name as contract_name, fp.contract_number as main_contract_number, fpb.SERIAL_NUMBER, fpb.bp_id as BP_ID, hbm.bp_name, (select hbm.bp_name from fct_project_bp fpp,hls_bp_master hb where fpp.project_id=fp.project_id and fpp.credit_grantor_party='Y' and fpp.bp_id=hb.bp_id)as credit_grantor_name, fp.sign_date, fc.rate_valid_from, fc.rate_valid_to, CASE WHEN (fc.contract_status = 'TERMINATE' or fc.contract_status = 'END') THEN 'N' ELSE 'Y' END contract_status, CASE WHEN (fc.contract_status = 'TERMINATE' or fc.contract_status = 'END') THEN '否' ELSE '是' END contract_status_n, CASE WHEN hbm.bp_class = 'NP' THEN hbm.id_card_no ELSE hbm.loan_card_num END loan_card_num, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FCT.ACCOUNT_CURRENCY' AND scvb.VALUE = fpb.COMMUNAL_CURRENCY) AS COMMUNAL_CURRENCY, nvl(fpb.guarantee_amount, 0) guarantee_amount_str, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_GUARANTEE_FORM' AND scvb.value = fpb.guarantee_type) AS guarantee_type, ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FCT.ACCOUNT_CURRENCY' AND scvb.VALUE = fpb.COMMUNAL_OTHER_CURRENCY) AS COMMUNAL_OTHER_CURRENCY, fpb.MORTGAGE_EVALUATION_DATE, fpb.MORTGAGE_EVALUATION_NAME, fpb.MORTGAGE_EVALUATION_CODE, CASE WHEN fpb.BP_ROLE_TYPE = 'PLEDGOR' THEN ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_PLEDGE_CATEGORY' AND scvb.VALUE = fpb.COLLATERAL_TYPE) WHEN fpb.BP_ROLE_TYPE = 'MORTGAGOR' THEN ( SELECT scvb.MEANING FROM SYS_CODE_VALUE_B scvb LEFT JOIN SYS_CODE_B scb ON scb.CODE_ID = scvb.CODE_ID WHERE scb.CODE = 'FND_MORTGAGE_CATEGORY' AND scvb.VALUE = fpb.COLLATERAL_TYPE) ELSE fpb.COLLATERAL_TYPE END AS COLLATERAL_TYPE, fpb.REGISTRATION_AUTHORITY, fpb.REGISTRATION_DATE, fpb.MORTGAGE_DESC, fpb.COLLATERAL_CODE, nvl(fpb.COMMUNAL_VALUE, 0) COMMUNAL_VALUE, fpb.EXPIRY_DATE, fpb.REMARKS AS REMARKS FROM fct_project_bp fpb LEFT JOIN hls_bp_master hbm ON hbm.bp_id = fpb.bp_id LEFT JOIN FCT_CONTRACT fc ON fpb.PROJECT_ID = fc.PROJECT_ID LEFT JOIN fct_PROJECT fp ON fp.PROJECT_ID = fc.PROJECT_ID LEFT JOIN ( SELECT fpb.PROJECT_ID, hbm.BP_NAME FROM fct_PROJECT_BP fpb LEFT JOIN hls_bp_master hbm ON fpb.BP_ID = hbm.BP_ID WHERE fpb.credit_grantor_party='Y' ) ta ON ta.project_id = fpb.project_id WHERE fpb.PROJECT_ID IS NOT NULL and fp.project_id=fpb.project_id and hbm.bp_id = fpb.bp_id and fp.data_class='VIRTUAL_CON' AND fp.data_type='NORMAL' AND fc.DATA_CLASS = 'NORMAL' AND ( fc.CONTRACT_STATUS IN ('INCEPT', 'TERMINATE','END') OR ( fc.CONTRACT_STATUS = 'PENDING' AND ( SELECT COUNT(0) FROM fct_CONTRACT fcc WHERE fcc.ref_contract_id = fc.contract_id AND fcc.contract_status = 'INCEPT' AND fcc.data_class = 'CHANGE_REQ' )> 0 ) )
and fpb.project_id=#{projectId}
and fpb.bp_role_type=#{bpRoleType}
and fpb.bp_role_type in ('SELLER','BUYER')
and fpb.credit_grantor_party=#{creditGrantorParty}
AND hbm.bp_name like '%'||#{bpName}||'%'
AND ta.bp_name like '%'||#{creditGrantorName}||'%'
AND fc.contract_name like '%'||#{contractName}||'%'
AND hbm.bp_code like '%'||#{bpCode}||'%'
AND fpb.project_bp_id = #{projectBpId} ) tab where 1=1
and tab.business_type = #{businessType}
and tab.contract_status = #{contractStatus}

SELECT tab.* FROM( select ( select hbm.bp_class from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_class, ( select hbm.phone from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as phone, ( select hbm.TAXPAYER_TYPE from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as TAXPAYER_TYPE, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb,hls_bp_master hbm where hbm.bp_id=fpb.bp_id and scvb.code_id = scb.code_id and scb.code = 'FND.TAXPAYER_TYPE' and scvb.value = hbm.TAXPAYER_TYPE )as TAXPAYER_TYPE_DESC, ( select hbm.INVOICE_TITLE from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_TITLE, ( select hbm.INVOICE_BP_ADDRESS_PHONE_NUM from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_BP_ADDRESS_PHONE_NUM, ( select hbm.INVOICE_BP_BANK_ACCOUNT from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as INVOICE_BP_BANK_ACCOUNT, ( select hbm.bp_code from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_code, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=fpb.bp_id )as bp_name, ( select hbt.description from hls_bp_type hbt where hbt.bp_type=fpb.bp_role_type )as prj_role, ( SELECT hbm.LOAN_CARD_NUM FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS LOAN_CARD_NUM, ( SELECT hbm.ID_TYPE FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS ID_TYPE, ( SELECT hbm.ID_CARD_NO FROM hls_bp_master hbm WHERE hbm.bp_id = fpb.bp_id ) AS ID_CARD_NO, (select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.bp_role_type and scb.code='FCT.BP_TYPE') as bpRoleTypeDesc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.communal_currency and scb.code='FCT.ACCOUNT_CURRENCY' ) as communal_currency_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.communal_other_currency and scb.code='FCT.ACCOUNT_CURRENCY' ) as communal_other_currency_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.guarantee_type and scb.code='FND_GUARANTEE_FORM' )as guarantee_type_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.np_guarantee_type and scb.code='NP.GUARANTEE_TYPE' )as np_guarantee_type_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.secured_party and scb.code='SECURED_PARTY' )as secured_party_desc, ( select scvb.meaning from sys_code_value_b scvb,sys_code_b scb where scb.code_id=scvb.code_id and scvb.value=fpb.collateral_type and scb.code in ('FND_MORTGAGE_CATEGORY', 'FND_PLEDGE_CATEGORY') ) as collateral_type_desc, fpb.serial_number, fpb.contract_number, fpb.project_bp_id, fpb.project_id, fpb.chance_id, fpb.bp_id, fpb.bp_role_type, fpb.credit_grantor_party, fpb.principal_repayment_party, fpb.interest_repayment_party, fpb.down_repayment_party, fpb.use_fee_repayment_party, fpb.compensation_repayment_party, fpb.repay_guarantee_party, fpb.guarantee_type, fpb.guarantee_amount, fpb.mortgage_guarantee_amount, fpb.mortgage_gua_amt_capital, fpb.mortgage_rate, fpb.mortgage_available_amount, fpb.mortgage_avail_amt_capital, fpb.pledge_amount, fpb.pledge_amount_capital, fpb.pledge_rate, fpb.repay_guarantee_sub_amount, fpb.description, fpb.bank_account_id, fpb.address_id, fpb.contact_info_id, fpb.COMMUNAL_CURRENCY, fpb.COMMUNAL_OTHER_CURRENCY, fpb.COMMUNAL_VALUE, fpb.MORTGAGE_EVALUATION_DATE, fpb.MORTGAGE_EVALUATION_NAME, fpb.MORTGAGE_EVALUATION_CODE, fpb.COLLATERAL_TYPE, fpb.REGISTRATION_AUTHORITY, fpb.REGISTRATION_DATE, fpb.MORTGAGE_DESC, fpb.COLLATERAL_CODE, fpb.NP_GUARANTEE_TYPE, fpb.SECURED_PARTY, fpb.EXPIRY_DATE, HBMBA.BANK_ACCOUNT_NUM, HBMBA.BANK_ACCOUNT_NAME, HBMBA.BANK_FULL_NAME, HBMBA.BANK_BRANCH_NAME, concat(concat(concat(concat(HBMA.country, ( SELECT t1.DESCRIPTION FROM FND_PROVINCE t1 WHERE t1.province = HBMA.province )), ( SELECT t1.DESCRIPTION FROM FND_CITY t1 WHERE t1.city = HBMA.city )), ( SELECT t1.DESCRIPTION FROM FND_DISTRICT t1 WHERE t1.district = HBMA.district)), HBMA.address) as addressInfo, concat(HBMCI.CONTACT_PERSON,HBMCI.CELL_PHONE) as contact_info from fct_project_bp fpb left join Hls_Bp_Master_Bank_Account HBMBA on fpb.BANK_ACCOUNT_ID=HBMBA.BANK_ACCOUNT_ID left join hls_bp_master_address HBMA on HBMA.ADDRESS_ID=fpb.ADDRESS_ID left join hls_bp_master_contact_info HBMCI on HBMCI.CONTACT_INFO_ID=fpb.CONTACT_INFO_ID ORDER BY fpb.CREATION_DATE ASC )tab
1 = 1
and tab.project_id=#{projectId}
and tab.chance_id=#{chanceId}
and tab.bp_role_type=#{bpRoleType}
and tab.bp_role_type in ('SELLER','BUYER')
and tab.credit_grantor_party=#{creditGrantorParty}
and tab.credit_grantor_party != 'Y' and tab.bp_class = #{bpClass}
AND tab.bp_name like concat('%',concat(#{bpName},'%'))
AND tab.bp_code like concat('%',concat(#{bpCode},'%'))
and (1=2
or tab.repay_guarantee_party ='Y'
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 or tab.principal_repayment_party ='Y'
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 or tab.interest_repayment_party ='Y'
-- 这里只是借用sellerAndBuyer作为bp_id集合的载体 or tab.use_fee_repayment_party ='Y' )
